command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="9b468483d7dc259564a142396d7ee29f123ede73"
$candidate="1ceb0699c2c3162eae50e7392cf3fab102019e7c"
$built="dfc8703394e8c750beaaaa7ee9cea9d81ddeba2c"
Set-Location -LiteralPath $repo
& git fetch origin main work/shell-provider-copyin-20261008 --no-tags --prune
if($LASTEXITCODE -ne 0){throw "fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved"}
if((& git rev-parse refs/remotes/origin/work/shell-provider-copyin-20261008).Trim() -ne $candidate){throw "candidate mismatch"}
$dirty=@(& git status --porcelain=v1 -uall)
if($dirty.Count -ne 0){$dirty|%{Write-Host ("UNEXPECTED_WORKTREE="+$_)};throw "checkout dirty"}
& git diff --quiet $built $candidate -- app/winui src/base tests/winui
if($LASTEXITCODE -ne 0){throw "product or test source changed after GUI PASS"}
try {
 & git switch --detach $candidate
 if($LASTEXITCODE -ne 0){throw "checkout failed"}
 & .\test.bat policy
 if($LASTEXITCODE -ne 0){throw "policy failed"}
 & git diff --check $main $candidate
 if($LASTEXITCODE -ne 0){throw "diff check failed"}
 Write-Host "SHELL_PROVIDER_COPYIN_DOCS_POLICY=PASS"
} finally {
 & git switch main
 if($LASTEXITCODE -ne 0){throw "restore main failed"}
 & git merge --ff-only origin/main
 if($LASTEXITCODE -ne 0){throw "restore main ff failed"}
}
